import {
  el,
  isSignalHandle,
  type AttrValue,
  type ChildNode,
  type ElProps,
  type Mountable,
  type PropValue,
} from '@llui/dom'
import {
  createVariants,
  type VariantConfig,
  type VariantProps,
  type VariantRecord,
} from '@llui/components/styles'
import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * Merge class strings, letting later Tailwind utilities win over earlier ones.
 *
 * This is NOT `cx` from `@llui/components/styles`. `cx` concatenates and filters
 * falsy values, so a caller override (`class: 'p-2'`) loses to a recipe's `p-4`
 * by source order — the caller's intent is silently dropped. `cn` resolves the
 * conflict, which is what makes `class` a real override slot on every component
 * in this directory.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs))
}

/**
 * Merge a component's recipe with the caller's `class` prop, preserving
 * reactivity when the caller passed a Signal.
 *
 * Every component here routes its `class` through this ONE function, and the
 * signal branch is why. `class` is typed `AttrValue = Reactive<string | …>`, so
 * a caller may legitimately pass `state.at('open').map(…)`. Handing that handle
 * to `cn()` stringifies it to `"[object Object]"` — a silently stuck attribute,
 * the exact failure `@llui/dom`'s `applyProp` exists to prevent for raw props.
 * Mapping instead keeps one reactive binding whose body sees plain values.
 *
 * Note the LLui-specific consequence for callers: the compiler rejects operators
 * applied to a Signal (`operator-on-signal`), so a state-driven class is written
 * INSIDE a `.map` body, never around one:
 *
 *   // wrong — `&&` applied to a Signal
 *   class: cn('base', state.at('open') && 'is-open')
 *   // right — one binding, plain values inside
 *   class: state.at('open').map((open) => cn('base', open && 'is-open'))
 *
 * Most state-driven styling should not need either form: every `@llui/components`
 * part already emits `data-state` / `data-disabled` / `data-orientation`, so
 * `data-[state=open]:…` in the recipe is the idiomatic answer.
 *
 * `override` is `unknown`, not `AttrValue`, because it is destructured out of an
 * `ElProps` bag whose index signature admits event handlers as well as attribute
 * values — a caller CAN hand this a function, and a narrower parameter type would
 * only push the cast to every one of the sixteen call sites. Both branches below
 * narrow before use, so a non-string, non-signal value contributes nothing.
 */
export function mergeClass(recipe: string, override: unknown): AttrValue {
  if (isSignalHandle(override)) {
    return override.map((value) => cn(recipe, toClass(value)))
  }
  return cn(recipe, toClass(override))
}

function toClass(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined
}

/**
 * The call shape every component in this directory accepts, matching `@llui/dom`'s
 * own `ElementHelper`: `Card(children)`, `Card(props, children)`, `Card(props)`,
 * or `Card()`. A leading array is children.
 *
 * The children-only form is not sugar. LLui's compiler makes `div({}, …)` a BUILD
 * ERROR (`empty-props`) — a throwaway object on the element mount path, the hot
 * path for list rendering — so a registry whose only call form required `{}` would
 * push every consumer into writing the shape the framework bans two lines away.
 */
export interface PartHelper {
  (children: readonly ChildNode[]): Mountable
  (props?: ElProps, children?: readonly ChildNode[]): Mountable
}

/** Normalise the two call forms. Exported because the components that are not
 * plain `classPart`s (Button, Separator, the overlay parts) need it too. */
export function splitArgs(
  a0?: ElProps | readonly ChildNode[],
  a1?: readonly ChildNode[],
): { props: ElProps; children: readonly ChildNode[] } {
  const leadingChildren = Array.isArray(a0)
  return {
    props: (leadingChildren ? undefined : (a0 as ElProps | undefined)) ?? {},
    children: (leadingChildren ? (a0 as readonly ChildNode[]) : a1) ?? [],
  }
}

/**
 * Build a fixed-recipe element helper: a tag, a class recipe, and a caller bag
 * whose `class` overrides.
 *
 * Most parts in this directory are exactly that and nothing more, so they are
 * generated from ONE seam rather than restated per part. The deduplication is
 * the smaller half of the reason. The larger half is that the repo's Tailwind
 * check reads class recipes out of the AST at the positions it knows about, and
 * a per-file copy of this factory is a position it does NOT know about — three
 * components' recipes were invisible to it until they came through here. A
 * recipe the checker cannot see is a recipe that can quietly stop producing CSS,
 * which is the whole defect this registry exists to have fixed.
 */
export function classPart(
  tag: (props?: ElProps, children?: readonly ChildNode[]) => Mountable,
  recipe: string,
): PartHelper {
  return ((a0?: ElProps | readonly ChildNode[], a1?: readonly ChildNode[]): Mountable => {
    const { props, children } = splitArgs(a0, a1)
    const { class: className, ...rest } = props
    return tag({ ...rest, class: mergeClass(recipe, className) }, children)
  }) as PartHelper
}

/**
 * `classPart` that also supplies DEFAULT attributes the caller may override.
 *
 * shadcn's components are React functions with default PROPS — `size =
 * "default"`, `variant = "default"` — and the recipe then keys off the
 * resulting `data-size` / `data-variant`. A recipe-only port keeps the classes
 * and silently loses the default, so a caller who does not think to pass
 * `data-size` gets an element whose `data-[size=default]:` rules never match.
 *
 * That is not a cosmetic loss. `Switch` puts its ENTIRE geometry behind
 * `data-[size=default]:h-[1.15rem] w-8` and its thumb behind
 * `group-data-[size=default]/switch:size-4`, so without the attribute the
 * control renders as a ~2px sliver with an invisible thumb — it toggles
 * correctly and looks like nothing happened. Measured in the demo.
 *
 * Defaulting here rather than editing the recipe keeps the recipe byte-identical
 * to upstream, which is the registry's standing rule.
 */
export function classPartWithDefaults(
  tag: (props?: ElProps, children?: readonly ChildNode[]) => Mountable,
  recipe: string,
  defaults: Record<string, unknown>,
): PartHelper {
  return ((a0?: ElProps | readonly ChildNode[], a1?: readonly ChildNode[]): Mountable => {
    const { props, children } = splitArgs(a0, a1)
    const { class: className, ...rest } = props
    // `defaults` FIRST so an explicit caller value wins.
    return tag({ ...defaults, ...rest, class: mergeClass(recipe, className) }, children)
  }) as PartHelper
}

export type { ClassValue }

/**
 * A `classPart`-built root wrapper is a plain function; nothing stops a
 * caller from constructing it without a machine's `exitCompletion` Mountable
 * placed anywhere in the same build, and README.md used to claim "registry
 * skins place it automatically" while `accordion.ts`/`collapsible.ts` were
 * ordinary `classPart(div, ...)` wrappers that never touched it (#264 review
 * item 2). `exitCompletion` settles a RETAINED close/toggle/setValue (one
 * stamped `retain: true`, e.g. via `parts.close(...)`) on a skin with no
 * exit motion; a raw programmatic `send` with no `retain` closes instantly
 * and never enters `closing`, so there is nothing for it to settle.
 *
 * **Forgetting it is no longer a hang (#264 item F1).** Whether
 * `exitCompletion` is CURRENTLY mounted lives in a runtime registry keyed by
 * the machine's own `opts.id` (#264 review-264j — never in state or a
 * message), and the reducer only ever retains `closing` when the
 * closing-capable message itself carries `retain: true`, which `connect()`'s
 * trigger handlers stamp from that registry — otherwise it closes instantly,
 * with a synchronous, once-per-id dev-mode `console.warn` (never a build
 * error). So `exitCompletion` is no longer required for SAFETY. It is kept
 * REQUIRED here anyway, and a root wrapper still cannot forget to append
 * what it is compile-time REQUIRED to accept.
 *
 * **`exitCompletion` is a SEPARATE third argument, never a field on the
 * attribute props bag (#264 post-merge fix).** It used to be a non-optional
 * field on `DisclosureRootProps = ElProps & { exitCompletion: Mountable }` —
 * reasoning (correctly, for how the TYPE is declared) that an intersection
 * of two separately-declared types does not force `exitCompletion` to
 * conform to `ElProps`'s own string index signature the way an `interface X
 * extends ElProps` would. That reasoning does not cover how a call site's
 * own fresh object LITERAL is checked: assigning `{ ...parts.root,
 * exitCompletion: parts.exitCompletion }` to `DisclosureRootProps` still
 * fails, because TypeScript flattens an intersection when checking a fresh
 * literal's properties against whichever index signature is reachable
 * through ANY constituent — so `exitCompletion`, a `Mountable`, is checked
 * against `ElProps`'s `AttrValue | ((e: Event) => void) | undefined` index
 * signature and rejected. This was invisible in this package's own suite
 * (which never assembled the literal that exact way in a real `tsc` run of
 * a DEMO package) and surfaced only once one finally did. The fix: keep
 * `exitCompletion` required, but pass it as its own argument — never
 * intersected into the attribute bag at all, so there is no shared index
 * signature for a fresh literal to be checked against in the first place.
 * `Accordion({ ...parts.root }, [...])` (missing the third argument) is
 * still a type error; `Accordion({ ...parts.root }, [...], {
 * exitCompletion: parts.exitCompletion })` is the whole call.
 */
export interface ExitCompletionOptions {
  /** `parts.exitCompletion` from the machine's `connect()` — see
   * `@llui/components`'s README ("accordion / collapsible exit motion"). */
  exitCompletion: Mountable
}

/**
 * Wrap a `classPart`-built disclosure root so it owns appending its own
 * machine's `exitCompletion` Mountable, rather than leaving that to callers
 * (demos included) to remember. `part` is still built via `classPart`
 * (never a bespoke `tag(...)` call) so the recipe string stays visible to
 * `scripts/lib/registry-classes.mjs`'s AST extractor, which only recognizes
 * string-literal recipes passed to a fixed set of call names.
 */
export function withExitCompletion(
  part: PartHelper,
): (props: ElProps, children: readonly ChildNode[], options: ExitCompletionOptions) => Mountable {
  return (
    props: ElProps,
    children: readonly ChildNode[],
    options: ExitCompletionOptions,
  ): Mountable => {
    return part(props, [...children, options.exitCompletion])
  }
}

/**
 * `classPart` with variants: a tag plus a `createVariants` recipe, where the
 * caller's variant keys are destructured out of the props bag before the rest is
 * spread onto the element.
 *
 * Without this, every variant-bearing component restates the same six lines of
 * destructure-resolve-merge. It also keeps the recipe inside a `createVariants`
 * call, which is a position the repo's Tailwind check reads in full — a recipe
 * assembled any other way is only partially checked.
 */
export function createVariantsPart<V extends VariantRecord>(
  tag: (props?: ElProps, children?: readonly ChildNode[]) => Mountable,
  config: VariantConfig<V>,
  /** Default ATTRIBUTES (not variants) the caller may override — the same
   * `size = "default"`-style prop default `classPartWithDefaults` restores.
   * Needed here whenever a SIBLING recipe reads the value off the DOM through
   * `peer-data-[…]` / `group-data-[…]`, because a variant resolved to a class
   * leaves nothing on the element for the sibling to match. */
  defaults: Record<string, unknown> = {},
): (
  a0?: (ElProps & { [K in keyof V]?: keyof V[K] }) | readonly ChildNode[],
  a1?: readonly ChildNode[],
) => Mountable {
  const recipe = createVariants(config)
  const keys = Object.keys(config.variants)
  return (a0, a1) => {
    const { props, children } = splitArgs(a0 as ElProps | readonly ChildNode[], a1)
    const rest: Record<string, unknown> = {}
    const chosen: Record<string, unknown> = {}
    for (const key of Object.keys(props)) {
      if (keys.includes(key)) chosen[key] = props[key]
      else rest[key] = props[key]
    }
    const { class: className, ...attrs } = rest
    return tag(
      {
        ...defaults,
        ...(attrs as ElProps),
        class: mergeClass(recipe(chosen as VariantProps<V>), className),
      },
      children,
    )
  }
}

/**
 * Element helper for a tag `@llui/dom` does not export a named helper for
 * (`<kbd>`, `<output>`, …).
 *
 * `el` takes `Record<string, PropValue>`, and `PropValue` does NOT admit
 * `undefined` while `ElProps`'s index signature does — an optional prop left off
 * a spread is `undefined`, so the two are not directly assignable. Dropping
 * undefined entries here is the honest adaptation; casting between them hides a
 * real difference and would let a stray `undefined` reach `applyAttr`.
 */
export function customTag(tag: string): PartHelper {
  return ((a0?: ElProps | readonly ChildNode[], a1?: readonly ChildNode[]): Mountable => {
    const { props, children } = splitArgs(a0, a1)
    const lowered: Record<string, PropValue> = {}
    for (const key of Object.keys(props)) {
      const value = props[key]
      if (value !== undefined) lowered[key] = value as PropValue
    }
    return el(tag, lowered, children)
  }) as PartHelper
}
